-- Flashcards PSCPP por matéria/bibliografia — lote inicial estratégico
-- Estrutura compatível com o banco separado de flashcards.

INSERT INTO decks (slug,subject_slug,subject_label,title,description,cards,is_active,sort_order,updated_at)
VALUES ('pscpp-manobrabilidade','manobrabilidade','Manobrabilidade','Manobrabilidade — Revisão Estratégica','Flashcards estratégicos de Manobrabilidade, organizados segundo a bibliografia oficial cadastrada na plataforma PSCPP.',$JSON$[{"id":"PSCPP-MANOBRABILIDADE-001","code":"01","name":"Efeito de banco","category":"interacao","pt":"Força e momento hidrodinâmicos decorrentes da assimetria do escoamento quando o navio navega próximo a uma margem ou banco, podendo produzir atração da popa e afastamento da proa.","en":"Força e momento hidrodinâmicos decorrentes da assimetria do escoamento quando o navio navega próximo a uma margem ou banco, podendo produzir atração da popa e afastamento da proa.","note":"Macete: Menor UKC e maior velocidade tendem a intensificar os efeitos de interação.","tags":["manobrabilidade","interacao","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-MANOBRABILIDADE-002","code":"02","name":"Squat","category":"aguas-rasas","pt":"Aumento do calado e alteração do trim do navio em movimento, associados à queda de pressão causada pelo escoamento acelerado ao redor do casco.","en":"Aumento do calado e alteração do trim do navio em movimento, associados à queda de pressão causada pelo escoamento acelerado ao redor do casco.","note":"Macete: Águas rasas e confinadas aumentam a relevância do squat.","tags":["manobrabilidade","aguas-rasas","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-MANOBRABILIDADE-003","code":"03","name":"Advance","category":"curva-giro","pt":"Distância medida na direção do rumo inicial, desde o início da guinada até uma posição especificada da curva de giro.","en":"Distância medida na direção do rumo inicial, desde o início da guinada até uma posição especificada da curva de giro.","note":"Macete: Associe advance ao avanço na direção original.","tags":["manobrabilidade","curva-giro","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-MANOBRABILIDADE-004","code":"04","name":"Transfer","category":"curva-giro","pt":"Distância transversal ao rumo inicial percorrida pelo navio durante a manobra de giro.","en":"Distância transversal ao rumo inicial percorrida pelo navio durante a manobra de giro.","note":"Macete: Transfer é o deslocamento lateral.","tags":["manobrabilidade","curva-giro","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-MANOBRABILIDADE-005","code":"05","name":"Diâmetro tático","category":"curva-giro","pt":"Distância transversal entre o rumo inicial e a posição do navio após completar aproximadamente 180° de mudança de rumo na curva de giro.","en":"Distância transversal entre o rumo inicial e a posição do navio após completar aproximadamente 180° de mudança de rumo na curva de giro.","note":"Macete: É parâmetro clássico dos padrões IMO de manobrabilidade.","tags":["manobrabilidade","curva-giro","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-MANOBRABILIDADE-006","code":"06","name":"Stopping ability","category":"parada","pt":"Capacidade de interromper o avanço do navio após uma ordem de parada, avaliada por parâmetros como track reach na manobra de crash stop.","en":"Capacidade de interromper o avanço do navio após uma ordem de parada, avaliada por parâmetros como track reach na manobra de crash stop.","note":"Macete: Não confunda distância de parada com tempo de parada.","tags":["manobrabilidade","parada","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-MANOBRABILIDADE-007","code":"07","name":"Cavitação do propulsor","category":"propulsao","pt":"Formação e colapso de cavidades de vapor em regiões de baixa pressão nas pás do propulsor, podendo reduzir desempenho, gerar ruído, vibração e erosão.","en":"Formação e colapso de cavidades de vapor em regiões de baixa pressão nas pás do propulsor, podendo reduzir desempenho, gerar ruído, vibração e erosão.","note":"Macete: Pressão local baixa é a chave para entender cavitação.","tags":["manobrabilidade","propulsao","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-MANOBRABILIDADE-008","code":"08","name":"Estabilidade direcional","category":"controlabilidade","pt":"Tendência do navio de manter ou recuperar uma trajetória aproximadamente retilínea após pequenas perturbações, conforme sua estabilidade dinâmica de rumo.","en":"Tendência do navio de manter ou recuperar uma trajetória aproximadamente retilínea após pequenas perturbações, conforme sua estabilidade dinâmica de rumo.","note":"Macete: Estabilidade direcional e capacidade de guinada são qualidades relacionadas, mas distintas.","tags":["manobrabilidade","controlabilidade","pscpp-2027","revisao-estrategica"]}]$JSON$::jsonb,true,20,now())
