INSERT INTO decks (slug,subject_slug,subject_label,title,description,cards,is_active,sort_order,updated_at)
VALUES ('pscpp-arte-naval','arte-naval','Arte Naval','Arte Naval — Revisão Estratégica','Flashcards estratégicos de Arte Naval, organizados segundo a bibliografia oficial cadastrada na plataforma PSCPP.',$JSON$[{"id":"PSCPP-ARTE_NAVAL-001","code":"01","name":"Centro de gravidade (G)","category":"estabilidade","pt":"Ponto no qual se considera aplicada a resultante dos pesos que compõem o navio.","en":"Ponto no qual se considera aplicada a resultante dos pesos que compõem o navio.","note":"Macete: A posição de G depende da distribuição dos pesos.","tags":["arte-naval","estabilidade","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-ARTE_NAVAL-002","code":"02","name":"Centro de carena (B)","category":"estabilidade","pt":"Centro geométrico do volume imerso; é o ponto de aplicação da resultante do empuxo hidrostático.","en":"Centro geométrico do volume imerso; é o ponto de aplicação da resultante do empuxo hidrostático.","note":"Macete: B se desloca quando muda a geometria do volume imerso.","tags":["arte-naval","estabilidade","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-ARTE_NAVAL-003","code":"03","name":"Metacentro transversal (M)","category":"estabilidade","pt":"Ponto geométrico associado à interseção das verticais de empuxo para pequenas inclinações transversais.","en":"Ponto geométrico associado à interseção das verticais de empuxo para pequenas inclinações transversais.","note":"Macete: GM é uma medida fundamental da estabilidade inicial.","tags":["arte-naval","estabilidade","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-ARTE_NAVAL-004","code":"04","name":"GM positivo","category":"estabilidade","pt":"Condição em que o metacentro está acima do centro de gravidade, produzindo estabilidade inicial positiva para pequenas inclinações.","en":"Condição em que o metacentro está acima do centro de gravidade, produzindo estabilidade inicial positiva para pequenas inclinações.","note":"Macete: M acima de G → GM positivo.","tags":["arte-naval","estabilidade","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-ARTE_NAVAL-005","code":"05","name":"GM negativo","category":"estabilidade","pt":"Condição em que o centro de gravidade está acima do metacentro, caracterizando estabilidade inicial negativa.","en":"Condição em que o centro de gravidade está acima do metacentro, caracterizando estabilidade inicial negativa.","note":"Macete: G acima de M → GM negativo; pode ocorrer ângulo de loll.","tags":["arte-naval","estabilidade","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-ARTE_NAVAL-006","code":"06","name":"Ângulo de loll","category":"estabilidade","pt":"Ângulo de equilíbrio assumido por um navio com estabilidade inicial negativa, quando o centro de gravidade está acima do metacentro na posição aprumada.","en":"Ângulo de equilíbrio assumido por um navio com estabilidade inicial negativa, quando o centro de gravidade está acima do metacentro na posição aprumada.","note":"Macete: Loll não é banda causada simplesmente por peso fora do centro.","tags":["arte-naval","estabilidade","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-ARTE_NAVAL-007","code":"07","name":"GZ","category":"estabilidade","pt":"Braço de endireitamento: distância horizontal entre as linhas de ação do peso e do empuxo para determinado ângulo de inclinação.","en":"Braço de endireitamento: distância horizontal entre as linhas de ação do peso e do empuxo para determinado ângulo de inclinação.","note":"Macete: Momento de endireitamento = deslocamento × GZ.","tags":["arte-naval","estabilidade","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-ARTE_NAVAL-008","code":"08","name":"Escada de prático","category":"pilotagem","pt":"Arranjo de transferência de prático sujeito aos requisitos da SOLAS V/23 e às recomendações/resoluções IMO aplicáveis.","en":"Arranjo de transferência de prático sujeito aos requisitos da SOLAS V/23 e às recomendações/resoluções IMO aplicáveis.","note":"Macete: Memorize a relação SOLAS V/23 + instrumentos IMO sobre pilot transfer arrangements.","tags":["arte-naval","pilotagem","pscpp-2027","revisao-estrategica"]}]$JSON$::jsonb,true,21,now())
