INSERT INTO decks (slug,subject_slug,subject_label,title,description,cards,is_active,sort_order,updated_at)
VALUES ('pscpp-navegacao-aguas-restritas','navegacao-aguas-restritas','Navegação em Águas Restritas','Navegação em Águas Restritas — Revisão Estratégica','Flashcards estratégicos de Navegação em Águas Restritas, organizados segundo a bibliografia oficial cadastrada na plataforma PSCPP.',$JSON$[{"id":"PSCPP-NAVEGACAO_AGUAS_RESTRITAS-001","code":"01","name":"Regra 5 do COLREG","category":"colreg","pt":"Todo navio deve manter, permanentemente, vigilância apropriada por visão e audição, bem como por todos os meios disponíveis adequados às circunstâncias e condições predominantes, para permitir plena avaliação da situação e do risco de abalroamento.","en":"Todo navio deve manter, permanentemente, vigilância apropriada por visão e audição, bem como por todos os meios disponíveis adequados às circunstâncias e condições predominantes, para permitir plena avaliação da situação e do risco de abalroamento.","note":"Macete: Vigilância é permanente e usa todos os meios apropriados.","tags":["navegacao-aguas-restritas","colreg","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-NAVEGACAO_AGUAS_RESTRITAS-002","code":"02","name":"Velocidade de segurança","category":"colreg","pt":"Velocidade que permita ação apropriada e eficaz para evitar abalroamento e possibilite parar dentro de distância adequada às circunstâncias e condições predominantes.","en":"Velocidade que permita ação apropriada e eficaz para evitar abalroamento e possibilite parar dentro de distância adequada às circunstâncias e condições predominantes.","note":"Macete: Não existe uma velocidade universalmente segura.","tags":["navegacao-aguas-restritas","colreg","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-NAVEGACAO_AGUAS_RESTRITAS-003","code":"03","name":"Risco de abalroamento","category":"colreg","pt":"Deve ser determinado utilizando todos os meios disponíveis apropriados; em caso de dúvida, considera-se que o risco existe.","en":"Deve ser determinado utilizando todos os meios disponíveis apropriados; em caso de dúvida, considera-se que o risco existe.","note":"Macete: Marcação constante com distância diminuindo é um indício clássico.","tags":["navegacao-aguas-restritas","colreg","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-NAVEGACAO_AGUAS_RESTRITAS-004","code":"04","name":"Passage plan","category":"btm","pt":"Planejamento da viagem desde o berço de partida até o berço de destino, incluindo avaliação, planejamento, execução e monitoramento.","en":"Planejamento da viagem desde o berço de partida até o berço de destino, incluindo avaliação, planejamento, execução e monitoramento.","note":"Macete: Appraisal → Planning → Execution → Monitoring.","tags":["navegacao-aguas-restritas","btm","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-NAVEGACAO_AGUAS_RESTRITAS-005","code":"05","name":"Parallel indexing","category":"radar","pt":"Técnica radar de monitoramento da posição e da distância lateral em relação a perigos ou referências, usando linhas paralelas de indexação.","en":"Técnica radar de monitoramento da posição e da distância lateral em relação a perigos ou referências, usando linhas paralelas de indexação.","note":"Macete: É ferramenta de monitoramento, não substitui fixação de posição.","tags":["navegacao-aguas-restritas","radar","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-NAVEGACAO_AGUAS_RESTRITAS-006","code":"06","name":"UKC","category":"aguas-rasas","pt":"Under Keel Clearance: separação vertical disponível entre a parte mais baixa do navio e o fundo, considerada segundo os critérios operacionais aplicáveis.","en":"Under Keel Clearance: separação vertical disponível entre a parte mais baixa do navio e o fundo, considerada segundo os critérios operacionais aplicáveis.","note":"Macete: UKC deve considerar fatores estáticos e dinâmicos.","tags":["navegacao-aguas-restritas","aguas-rasas","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-NAVEGACAO_AGUAS_RESTRITAS-007","code":"07","name":"Bridge Team Management","category":"btm","pt":"Aplicação organizada de pessoas, equipamentos, informações e procedimentos da ponte para condução segura da navegação.","en":"Aplicação organizada de pessoas, equipamentos, informações e procedimentos da ponte para condução segura da navegação.","note":"Macete: Comunicação, consciência situacional e challenge-response são centrais.","tags":["navegacao-aguas-restritas","btm","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-NAVEGACAO_AGUAS_RESTRITAS-008","code":"08","name":"Wheel-over point","category":"planejamento","pt":"Posição planejada na qual a guinada deve ser iniciada para que o navio estabeleça adequadamente a próxima pernada.","en":"Posição planejada na qual a guinada deve ser iniciada para que o navio estabeleça adequadamente a próxima pernada.","note":"Macete: Não confunda WOP com waypoint.","tags":["navegacao-aguas-restritas","planejamento","pscpp-2027","revisao-estrategica"]}]$JSON$::jsonb,true,22,now())
