INSERT INTO decks (slug,subject_slug,subject_label,title,description,cards,is_active,sort_order,updated_at)
VALUES ('pscpp-legislacao-regulamentacao','legislacao-regulamentacao','Legislação e Regulamentação','Legislação — Revisão Estratégica','Flashcards estratégicos de Legislação e Regulamentação, organizados segundo a bibliografia oficial cadastrada na plataforma PSCPP.',$JSON$[{"id":"PSCPP-LEGISLACAO_REGULAMENTACAO-001","code":"01","name":"LESTA","category":"lesta","pt":"Lei nº 9.537/1997, que dispõe sobre a segurança do tráfego aquaviário em águas sob jurisdição nacional e estabelece atribuições da Autoridade Marítima.","en":"Lei nº 9.537/1997, que dispõe sobre a segurança do tráfego aquaviário em águas sob jurisdição nacional e estabelece atribuições da Autoridade Marítima.","note":"Macete: LESTA = Lei 9.537/97.","tags":["legislacao-regulamentacao","lesta","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-LEGISLACAO_REGULAMENTACAO-002","code":"02","name":"RLESTA","category":"rlesta","pt":"Regulamento da Lei de Segurança do Tráfego Aquaviário, aprovado pelo Decreto nº 2.596/1998.","en":"Regulamento da Lei de Segurança do Tráfego Aquaviário, aprovado pelo Decreto nº 2.596/1998.","note":"Macete: RLESTA regulamenta a LESTA.","tags":["legislacao-regulamentacao","rlesta","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-LEGISLACAO_REGULAMENTACAO-003","code":"03","name":"Autoridade Marítima","category":"lesta","pt":"No âmbito da LESTA, suas atribuições são exercidas pelo Comando da Marinha, conforme a estrutura e competências legalmente estabelecidas.","en":"No âmbito da LESTA, suas atribuições são exercidas pelo Comando da Marinha, conforme a estrutura e competências legalmente estabelecidas.","note":"Macete: Diferencie Autoridade Marítima de seus agentes.","tags":["legislacao-regulamentacao","lesta","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-LEGISLACAO_REGULAMENTACAO-004","code":"04","name":"Capitão dos Portos","category":"lesta","pt":"Agente da Autoridade Marítima com competências administrativas e fiscalizatórias na respectiva jurisdição, conforme as normas aplicáveis.","en":"Agente da Autoridade Marítima com competências administrativas e fiscalizatórias na respectiva jurisdição, conforme as normas aplicáveis.","note":"Macete: CP/DL/AG integram a execução local das atribuições.","tags":["legislacao-regulamentacao","lesta","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-LEGISLACAO_REGULAMENTACAO-005","code":"05","name":"Tribunal Marítimo","category":"tribunal-maritimo","pt":"Órgão autônomo, auxiliar do Poder Judiciário, com atribuições legais relacionadas ao julgamento de acidentes e fatos da navegação e ao registro da propriedade marítima nos casos previstos.","en":"Órgão autônomo, auxiliar do Poder Judiciário, com atribuições legais relacionadas ao julgamento de acidentes e fatos da navegação e ao registro da propriedade marítima nos casos previstos.","note":"Macete: Lei nº 2.180/1954 é referência central.","tags":["legislacao-regulamentacao","tribunal-maritimo","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-LEGISLACAO_REGULAMENTACAO-006","code":"06","name":"Praticagem","category":"praticagem","pt":"Atividade baseada no conhecimento dos acidentes e pontos característicos da área em que é desenvolvida, destinada a auxiliar o comandante na condução segura do navio.","en":"Atividade baseada no conhecimento dos acidentes e pontos característicos da área em que é desenvolvida, destinada a auxiliar o comandante na condução segura do navio.","note":"Macete: O prático assessora; o comandante mantém suas responsabilidades legais.","tags":["legislacao-regulamentacao","praticagem","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-LEGISLACAO_REGULAMENTACAO-007","code":"07","name":"NORMAM","category":"normam","pt":"Normas da Autoridade Marítima que disciplinam matérias específicas dentro das competências atribuídas à Autoridade Marítima.","en":"Normas da Autoridade Marítima que disciplinam matérias específicas dentro das competências atribuídas à Autoridade Marítima.","note":"Macete: A numeração identifica séries e assuntos específicos.","tags":["legislacao-regulamentacao","normam","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-LEGISLACAO_REGULAMENTACAO-008","code":"08","name":"A.960(23)","category":"imo","pt":"Resolução da IMO com recomendações sobre treinamento, certificação e procedimentos operacionais para práticos marítimos que não sejam práticos de alto-mar.","en":"Resolução da IMO com recomendações sobre treinamento, certificação e procedimentos operacionais para práticos marítimos que não sejam práticos de alto-mar.","note":"Macete: Associe A.960(23) à praticagem.","tags":["legislacao-regulamentacao","imo","pscpp-2027","revisao-estrategica"]}]$JSON$::jsonb,true,23,now())
