INSERT INTO decks (slug,subject_slug,subject_label,title,description,cards,is_active,sort_order,updated_at)
VALUES ('pscpp-meteorologia-oceanografia','meteorologia-oceanografia','Meteorologia e Oceanografia','Meteorologia e Oceanografia — Revisão Estratégica','Flashcards estratégicos de Meteorologia e Oceanografia, organizados segundo a bibliografia oficial cadastrada na plataforma PSCPP.',$JSON$[{"id":"PSCPP-METEOROLOGIA_OCEANOGRAFIA-001","code":"01","name":"Gradiente vertical de temperatura","category":"atmosfera","pt":"Taxa de variação da temperatura do ar com a altitude.","en":"Taxa de variação da temperatura do ar com a altitude.","note":"Macete: Compare o gradiente ambiental com os gradientes adiabáticos para avaliar estabilidade.","tags":["meteorologia-oceanografia","atmosfera","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-METEOROLOGIA_OCEANOGRAFIA-002","code":"02","name":"Gradiente adiabático seco","category":"atmosfera","pt":"Taxa aproximada de variação da temperatura de uma parcela de ar não saturada submetida a deslocamento adiabático; cerca de 9,8 °C por km.","en":"Taxa aproximada de variação da temperatura de uma parcela de ar não saturada submetida a deslocamento adiabático; cerca de 9,8 °C por km.","note":"Macete: Aproximação de prova: ~1 °C/100 m.","tags":["meteorologia-oceanografia","atmosfera","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-METEOROLOGIA_OCEANOGRAFIA-003","code":"03","name":"Inversão térmica","category":"atmosfera","pt":"Camada em que a temperatura aumenta com a altitude, contrariando o comportamento médio da troposfera.","en":"Camada em que a temperatura aumenta com a altitude, contrariando o comportamento médio da troposfera.","note":"Macete: Inversões favorecem grande estabilidade vertical.","tags":["meteorologia-oceanografia","atmosfera","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-METEOROLOGIA_OCEANOGRAFIA-004","code":"04","name":"Isóbara","category":"cartas","pt":"Linha em uma carta meteorológica que une pontos de igual pressão atmosférica reduzida ao mesmo nível de referência.","en":"Linha em uma carta meteorológica que une pontos de igual pressão atmosférica reduzida ao mesmo nível de referência.","note":"Macete: Isóbaras próximas indicam gradiente horizontal de pressão mais intenso.","tags":["meteorologia-oceanografia","cartas","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-METEOROLOGIA_OCEANOGRAFIA-005","code":"05","name":"Vento geostrófico","category":"vento","pt":"Vento idealizado resultante do equilíbrio entre a força do gradiente de pressão e a força de Coriolis, desprezando atrito.","en":"Vento idealizado resultante do equilíbrio entre a força do gradiente de pressão e a força de Coriolis, desprezando atrito.","note":"Macete: É uma aproximação mais adequada longe da superfície.","tags":["meteorologia-oceanografia","vento","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-METEOROLOGIA_OCEANOGRAFIA-006","code":"06","name":"Maré astronômica","category":"mare","pt":"Oscilação periódica do nível do mar produzida principalmente pelas forças gravitacionais da Lua e do Sol e pela rotação do sistema Terra-Lua.","en":"Oscilação periódica do nível do mar produzida principalmente pelas forças gravitacionais da Lua e do Sol e pela rotação do sistema Terra-Lua.","note":"Macete: Não confunda maré astronômica com efeitos meteorológicos sobre o nível do mar.","tags":["meteorologia-oceanografia","mare","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-METEOROLOGIA_OCEANOGRAFIA-007","code":"07","name":"Fetch","category":"ondas","pt":"Extensão da superfície aquática sobre a qual o vento sopra com direção aproximadamente constante, contribuindo para geração das ondas.","en":"Extensão da superfície aquática sobre a qual o vento sopra com direção aproximadamente constante, contribuindo para geração das ondas.","note":"Macete: Vento + duração + fetch controlam o crescimento do mar.","tags":["meteorologia-oceanografia","ondas","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-METEOROLOGIA_OCEANOGRAFIA-008","code":"08","name":"Swell","category":"ondas","pt":"Ondulação que se propagou para fora da região de geração pelo vento, geralmente mais regular e organizada que o mar local.","en":"Ondulação que se propagou para fora da região de geração pelo vento, geralmente mais regular e organizada que o mar local.","note":"Macete: Swell pode chegar de uma direção diferente do vento local.","tags":["meteorologia-oceanografia","ondas","pscpp-2027","revisao-estrategica"]}]$JSON$::jsonb,true,24,now())
