INSERT INTO decks (slug,subject_slug,subject_label,title,description,cards,is_active,sort_order,updated_at)
VALUES ('pscpp-comunicacoes','comunicacoes','Comunicações','Comunicações — Revisão Estratégica','Flashcards estratégicos de Comunicações, organizados segundo a bibliografia oficial cadastrada na plataforma PSCPP.',$JSON$[{"id":"PSCPP-COMUNICACOES-001","code":"01","name":"SMCP","category":"smcp","pt":"Standard Marine Communication Phrases: conjunto padronizado de frases marítimas da IMO para reduzir ambiguidades na comunicação de segurança.","en":"Standard Marine Communication Phrases: conjunto padronizado de frases marítimas da IMO para reduzir ambiguidades na comunicação de segurança.","note":"Macete: Padronização reduz erros linguísticos.","tags":["comunicacoes","smcp","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-COMUNICACOES-002","code":"02","name":"Mayday","category":"gmdss","pt":"Sinal radiotelefônico de socorro empregado quando existe perigo grave e iminente e é necessária assistência imediata.","en":"Sinal radiotelefônico de socorro empregado quando existe perigo grave e iminente e é necessária assistência imediata.","note":"Macete: MAYDAY = distress.","tags":["comunicacoes","gmdss","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-COMUNICACOES-003","code":"03","name":"Pan-Pan","category":"gmdss","pt":"Sinal radiotelefônico de urgência para mensagem muito urgente relativa à segurança de uma estação móvel ou pessoa, sem caracterizar necessariamente socorro.","en":"Sinal radiotelefônico de urgência para mensagem muito urgente relativa à segurança de uma estação móvel ou pessoa, sem caracterizar necessariamente socorro.","note":"Macete: PAN-PAN = urgency.","tags":["comunicacoes","gmdss","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-COMUNICACOES-004","code":"04","name":"Sécurité","category":"gmdss","pt":"Sinal usado para anunciar mensagem de segurança importante, como avisos à navegação ou meteorológicos.","en":"Sinal usado para anunciar mensagem de segurança importante, como avisos à navegação ou meteorológicos.","note":"Macete: SÉCURITÉ = safety.","tags":["comunicacoes","gmdss","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-COMUNICACOES-005","code":"05","name":"Canal VHF 16","category":"vhf","pt":"Canal internacional associado a socorro, segurança e chamada em radiotelefonia marítima, conforme os procedimentos aplicáveis.","en":"Canal internacional associado a socorro, segurança e chamada em radiotelefonia marítima, conforme os procedimentos aplicáveis.","note":"Macete: Após estabelecer contato, tráfego de rotina deve migrar para canal apropriado.","tags":["comunicacoes","vhf","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-COMUNICACOES-006","code":"06","name":"DSC","category":"gmdss","pt":"Digital Selective Calling: técnica do GMDSS para chamadas digitais seletivas, inclusive alertas de socorro.","en":"Digital Selective Calling: técnica do GMDSS para chamadas digitais seletivas, inclusive alertas de socorro.","note":"Macete: DSC não é conversa por voz; inicia/coordena a chamada digital.","tags":["comunicacoes","gmdss","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-COMUNICACOES-007","code":"07","name":"MMSI","category":"gmdss","pt":"Maritime Mobile Service Identity: identidade numérica de nove algarismos usada para identificar estações e grupos em serviços móveis marítimos.","en":"Maritime Mobile Service Identity: identidade numérica de nove algarismos usada para identificar estações e grupos em serviços móveis marítimos.","note":"Macete: MMSI é identidade, não frequência.","tags":["comunicacoes","gmdss","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-COMUNICACOES-008","code":"08","name":"Código Internacional de Sinais","category":"cis","pt":"Sistema internacional de sinais destinado à comunicação de mensagens essenciais, especialmente relacionadas à segurança da navegação e das pessoas.","en":"Sistema internacional de sinais destinado à comunicação de mensagens essenciais, especialmente relacionadas à segurança da navegação e das pessoas.","note":"Macete: A plataforma já possui baralho específico do CIS.","tags":["comunicacoes","cis","pscpp-2027","revisao-estrategica"]}]$JSON$::jsonb,true,25,now())
