INSERT INTO decks (slug,subject_slug,subject_label,title,description,cards,is_active,sort_order,updated_at)
VALUES ('pscpp-conhecimentos-gerais','conhecimentos-gerais','Conhecimentos Gerais','Conhecimentos Gerais — Revisão Estratégica','Flashcards estratégicos de Conhecimentos Gerais, organizados segundo a bibliografia oficial cadastrada na plataforma PSCPP.',$JSON$[{"id":"PSCPP-CONHECIMENTOS_GERAIS-001","code":"01","name":"Amazônia Azul","category":"poder-maritimo","pt":"Conceito associado ao espaço marítimo brasileiro e à relevância estratégica, econômica, ambiental e de soberania das áreas marítimas de interesse do Brasil.","en":"Conceito associado ao espaço marítimo brasileiro e à relevância estratégica, econômica, ambiental e de soberania das áreas marítimas de interesse do Brasil.","note":"Macete: Relacione o conceito ao Poder Marítimo e aos interesses nacionais no mar.","tags":["conhecimentos-gerais","poder-maritimo","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-CONHECIMENTOS_GERAIS-002","code":"02","name":"Poder Marítimo","category":"poder-maritimo","pt":"Expressão ampla dos recursos e capacidades de uma nação relacionados ao uso do mar para alcançar objetivos e interesses nacionais.","en":"Expressão ampla dos recursos e capacidades de uma nação relacionados ao uso do mar para alcançar objetivos e interesses nacionais.","note":"Macete: É conceito mais amplo que Poder Naval.","tags":["conhecimentos-gerais","poder-maritimo","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-CONHECIMENTOS_GERAIS-003","code":"03","name":"Poder Naval","category":"poder-naval","pt":"Componente militar do Poder Marítimo, constituído pelos meios e capacidades navais empregados para contribuir para a defesa e os objetivos nacionais.","en":"Componente militar do Poder Marítimo, constituído pelos meios e capacidades navais empregados para contribuir para a defesa e os objetivos nacionais.","note":"Macete: Poder Naval ⊂ Poder Marítimo.","tags":["conhecimentos-gerais","poder-naval","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-CONHECIMENTOS_GERAIS-004","code":"04","name":"Mar territorial","category":"direito-mar","pt":"Faixa marítima adjacente ao território sobre a qual o Estado costeiro exerce soberania, observadas as regras do direito internacional aplicáveis.","en":"Faixa marítima adjacente ao território sobre a qual o Estado costeiro exerce soberania, observadas as regras do direito internacional aplicáveis.","note":"Macete: Diferencie mar territorial, zona contígua e ZEE.","tags":["conhecimentos-gerais","direito-mar","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-CONHECIMENTOS_GERAIS-005","code":"05","name":"ZEE","category":"direito-mar","pt":"Zona Econômica Exclusiva: área além e adjacente ao mar territorial na qual o Estado costeiro possui direitos de soberania e jurisdição específicos previstos no direito do mar.","en":"Zona Econômica Exclusiva: área além e adjacente ao mar territorial na qual o Estado costeiro possui direitos de soberania e jurisdição específicos previstos no direito do mar.","note":"Macete: ZEE não equivale a soberania territorial plena.","tags":["conhecimentos-gerais","direito-mar","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-CONHECIMENTOS_GERAIS-006","code":"06","name":"Plataforma continental","category":"direito-mar","pt":"Leito e subsolo das áreas submarinas que se estendem além do mar territorial, definidos segundo os critérios jurídicos da Convenção das Nações Unidas sobre o Direito do Mar.","en":"Leito e subsolo das áreas submarinas que se estendem além do mar territorial, definidos segundo os critérios jurídicos da Convenção das Nações Unidas sobre o Direito do Mar.","note":"Macete: Direitos sobre plataforma continental referem-se principalmente ao leito e subsolo.","tags":["conhecimentos-gerais","direito-mar","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-CONHECIMENTOS_GERAIS-007","code":"07","name":"SAR","category":"sar","pt":"Search and Rescue: organização e operações destinadas à busca e salvamento de pessoas em perigo.","en":"Search and Rescue: organização e operações destinadas à busca e salvamento de pessoas em perigo.","note":"Macete: No contexto marítimo, associe SAR à coordenação de busca e salvamento.","tags":["conhecimentos-gerais","sar","pscpp-2027","revisao-estrategica"]},{"id":"PSCPP-CONHECIMENTOS_GERAIS-008","code":"08","name":"Consciência situacional marítima","category":"seguranca-maritima","pt":"Compreensão do ambiente marítimo relevante para segurança, defesa, proteção, economia e outros interesses, construída a partir da integração e análise de informações.","en":"Compreensão do ambiente marítimo relevante para segurança, defesa, proteção, economia e outros interesses, construída a partir da integração e análise de informações.","note":"Macete: Informação isolada não é o mesmo que consciência situacional.","tags":["conhecimentos-gerais","seguranca-maritima","pscpp-2027","revisao-estrategica"]}]$JSON$::jsonb,true,26,now())
